mapper.select:
SELECT id, quiz_title, time_limit_minutes, pass_score, course_id, student_id, teacher_id, active, created_at, updated_at
FROM quizzes
WHERE id = #{quizId}

SELECT id, quiz_title, time_limit_minutes, pass_score, course_id, student_id, teacher_id, active, created_at, updated_at
FROM quizzes
WHERE id = #{quizId}
  AND course_id = #{courseId}

SELECT id, quiz_title, time_limit_minutes, pass_score, course_id, student_id, teacher_id, active, created_at, updated_at
FROM quizzes
WHERE course_id = #{courseId}
  AND teacher_id = #{teacherId}
ORDER BY created_at DESC
